diff --git a/ta4j-core/src/main/java/org/ta4j/core/indicators/CachedIndicator.java b/ta4j-core/src/main/java/org/ta4j/core/indicators/CachedIndicator.java
index e86152b85..6d99a0950 100644
--- a/ta4j-core/src/main/java/org/ta4j/core/indicators/CachedIndicator.java
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/CachedIndicator.java
@@ -1389,0 +1390,10 @@ public abstract class CachedIndicator<T> extends AbstractIndicator<T> {
+
+    /**
+     * Checks whether the specified index is already computed and cached.
+     *
+     * @param index the bar index
+     * @return true if the index is cached, false otherwise
+     */
+    protected boolean isCached(int index) {
+        return cache.isCached(index);
+    }
diff --git a/ta4j-core/src/main/java/org/ta4j/core/indicators/helpers/HighestValueIndicator.java b/ta4j-core/src/main/java/org/ta4j/core/indicators/helpers/HighestValueIndicator.java
index 41b696241..c049cf8cb 100644
--- a/ta4j-core/src/main/java/org/ta4j/core/indicators/helpers/HighestValueIndicator.java
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/helpers/HighestValueIndicator.java
@@ -5,0 +6 @@ package org.ta4j.core.indicators.helpers;
+import org.ta4j.core.BarSeries;
@@ -35,2 +36,20 @@ public class HighestValueIndicator extends CachedIndicator<Num> {
-        if (indicator.getValue(index).isNaN() && barCount != 1) {
-            return new HighestValueIndicator(indicator, barCount - 1).getValue(index - 1);
+        Num currentVal = indicator.getValue(index);
+
+        BarSeries series = indicator.getBarSeries();
+        int beginIndex = Math.max(0, series != null ? series.getBeginIndex() : 0);
+
+        if (currentVal.isNaN()) {
+            if (barCount == 1) {
+                return currentVal;
+            }
+            int end = Math.max(beginIndex, index - barCount + 1);
+            Num highest = currentVal;
+            for (int i = index - 1; i >= end; i--) {
+                Num val = indicator.getValue(i);
+                if (!val.isNaN()) {
+                    if (highest.isNaN() || highest.isLessThan(val)) {
+                        highest = val;
+                    }
+                }
+            }
+            return highest;
@@ -38,2 +57,20 @@ public class HighestValueIndicator extends CachedIndicator<Num> {
-        int end = Math.max(0, index - barCount + 1);
-        Num highest = indicator.getValue(index);
+
+        if (index > beginIndex && isCached(index - 1)) {
+            Num highestPrev = getValue(index - 1);
+            if (!highestPrev.isNaN()) {
+                if (currentVal.isGreaterThan(highestPrev)) {
+                    return currentVal;
+                }
+                int oldStartIndex = index - barCount;
+                if (oldStartIndex < beginIndex) {
+                    return highestPrev;
+                }
+                Num droppedVal = indicator.getValue(oldStartIndex);
+                if (droppedVal.isNaN() || highestPrev.isGreaterThan(droppedVal)) {
+                    return highestPrev;
+                }
+            }
+        }
+
+        int end = Math.max(beginIndex, index - barCount + 1);
+        Num highest = currentVal;
@@ -41,2 +78,5 @@ public class HighestValueIndicator extends CachedIndicator<Num> {
-            if (highest.isLessThan(indicator.getValue(i))) {
-                highest = indicator.getValue(i);
+            Num val = indicator.getValue(i);
+            if (!val.isNaN()) {
+                if (highest.isLessThan(val)) {
+                    highest = val;
+                }
