+                if (oldStartIndex < beginIndex) {
+                    return lowestPrev;
+                }
+                Num droppedVal = indicator.getValue(oldStartIndex);
+                if (droppedVal.isNaN() || lowestPrev.isLessThan(droppedVal)) {
+                    return lowestPrev;
+                }
+            }
